local _, WFJ = ...
WFJ.Data.add("book", {
  ["5316a95440d3842f"] = { "Tira fuori le ossa da quella cripta: c'è del lavoro da fare! La ⟦Scarlet Crusade=Crociata Scarlatta⟧ avanza rapida contro la nostra gente, e gli altri umani ci uccidono appena possono. Abbiamo bisogno della tua spada.\n\nQuando vorrai saperne di più sulle armi, vieni a cercarmi nella taverna in rovina di ⟦Deathknell=Albamorta⟧. Ti insegnerò io.\n\n-Dannal Stern, istruttore dei guerrieri.", "." },
  ["5343113a66b1d6e6"] = { "Ysera:\n\rYsera la Sognatrice rappresenta il subconscio dei mortali. Racchiude in sé il Sogno di Smeraldo.. Pur apprezzando l'immaginazione e la creazione e approvando l'ambizione nelle razze mortali, lei e il suo stormo considerano il mondo reale soltanto un'illusione. Ysera è una delle creature più aggraziate e potenti su cui un mortale possa posare lo sguardo.", "." },
  ["5364cb1312049984"] = { "Il titolare di questo certificato ha diritto al rispetto e alla considerazione che merita ogni scassinatore e ladro di prim'ordine.", "." },
  ["536d95c338be231d"] = { "Ci addolora dover dire che a noi di Snuff Inc. sono giunte segnalazioni di alcuni avidi cacciatori di tuberi a cui importa poco della sicurezza dei loro adorabili animali, e che li mandano in angoli e anfratti bui e pericolosi in cerca di tuberi.\n\nNon approviamo un comportamento così irresponsabile, ma per la soddisfazione dei clienti abbiamo incluso una garanzia con ogni tartasniffo venduto, che permette ai nuovi proprietari di tornare al punto vendita e sostituire gli animali perduti.\n\nBuona caccia!", "." },
  ["5379e001a07d8867"] = { "Toccò a ⟦Malfurion Stormrage=Malfurion Grantempesta⟧ trovare aiuto per il suo popolo assediato. Stormrage, il cui stesso fratello, Illidan, praticava la magia degli Alti Nobili, era indignato dalla crescente corruzione dell'aristocrazia. Convinto Illidan ad abbandonare la sua pericolosa ossessione, Malfurion partì alla ricerca di Cenarius per radunare una forza di resistenza.", "." },
  ["5394df64281cbcf2"] = { "Sotto la guida del venerabile sciamano ⟦Drek'Thar=Drek'thar⟧, Thrall studiò l'antica cultura sciamanica del suo popolo, dimenticata sotto il malvagio dominio di Gul'dan. Con il tempo Thrall divenne un potente sciamano e prese il posto che gli spettava come capo dei Lupi Bianchi esiliati. Forte del potere degli elementi stessi e spinto a compiere il proprio destino, Thrall partì per liberare i clan prigionieri e guarire la sua razza dalla corruzione demoniaca.", "." },
  ["539bae5ab9a95487"] = { "Scommetto che ti aspettavi un normale messaggio dal tuo re o da chissà chi. Be', diciamo solo che di biglietti falsificati me ne intendo un po', e volevo essere sicuro che ricevessi proprio questo. Non posso mica attirare l'attenzione su di me, giusto?\n\nMi sono rintanato dentro ⟦Anvilmar=Forgiamara⟧: mi troverai vicino al focolare. Quando te la senti, vieni a parlarmi. Voglio solo presentarmi finché abbiamo tempo.\n\n-Solm Hargrin, istruttore dei ladri", "." },
  ["53d4eb8036bdd08b"] = { "Spero che nessun mago di Dalaran vada in cerca dei worgen, nemmeno a cuor leggero. Perché con queste bestie non si può stringere alcun patto, non si può apprendere alcun segreto, non può nascere alcun bene.\n\nÈ meglio lasciarli nel loro mondo. Perché se venissero trovati nel nostro e non distrutti, il pericolo per noi sarebbe terribile...", "." },
  ["53df4e6d3fabd3df"] = { "I simboli e i pittogrammi vorticanti che riempiono le pagine di questo manuale sono esoterici oltre ogni comprensione.", "." },
  ["53e42a89ed28b228"] = { "si diresse verso il villaggio in cerca di risposte e, sperava, della moglie e dei figli.\n\nMorgan chiese notizie della sua famiglia, ma non trovò risposte. Un sacerdote di ⟦Darkshire=Borgoscuro⟧, come ora si chiamava il villaggio, gli disse che avrebbe potuto cercare una lapide nel cimitero di ⟦Raven Hill=Collecorvo⟧. Morgan si rifiutò di credere che la sua famiglia fosse morta e continuò a cercare in ogni fattoria e in ogni casa di ⟦Duskwood=Boscovespro⟧, ma invano.\n\nMorgan cavalcò da ⟦Darkshire=Borgoscuro⟧ fino alla vicina ⟦Lakeshire=Borgolago⟧, pensando che forse la sua famiglia fosse fuggita. Lungo la", "." },
})
